// Pick a topic for this week and build the full prompt context from the API response.
// Uses deterministic week-number rotation so re-runs produce same topic.

const ctx = $input.item.json;

const topicTemplates = [
  { topic: "best nightclubs in Gastown Vancouver", focus: "gastown", music: "house" },
  { topic: "top rooftop bars in Vancouver for summer", focus: "rooftop", music: null },
  { topic: "Granville Street nightlife guide Vancouver", focus: "granville", music: null },
  { topic: "best hip-hop nights in Vancouver clubs", focus: "hip-hop scene", music: "hip-hop" },
  { topic: "Yaletown cocktail bars Vancouver insider guide", focus: "yaletown", music: null },
  { topic: "Vancouver nightlife dress code guide what to wear", focus: "dress code", music: null },
  { topic: "best Latin nights in Vancouver where to dance salsa", focus: "latin", music: "latin" },
  { topic: "how to get on the guestlist at Vancouver clubs", focus: "guestlist tips", music: null },
  { topic: "Vancouver bottle service VIP table reservation guide", focus: "vip", music: null },
  { topic: "Coal Harbour bars and nightlife Vancouver", focus: "coal-harbour", music: null },
  { topic: "best techno and electronic music clubs in Vancouver", focus: "techno", music: "techno" },
  { topic: "Vancouver nightlife for tourists ultimate 2025 guide", focus: "tourists", music: null },
  { topic: "Vancouver afrobeats nights and African-Caribbean clubs", focus: "afrobeats", music: "afrobeats" },
  { topic: "best R&B nights in Vancouver — where to dance", focus: "r&b", music: "r&b" },
  { topic: "Vancouver bar hopping routes — neighbourhood by neighbourhood", focus: "bar hopping", music: null },
  { topic: "how to book a table reservation in Vancouver nightclub", focus: "reservations", music: null }
];

const week = Math.floor(Date.now() / (1000 * 60 * 60 * 24 * 7));
const pick = topicTemplates[week % topicTemplates.length];

// Build venue list for internal linking — only active venues
const venues = ctx.venues || [];
const venueLines = venues
  .filter(v => v.is_active)
  .map(v => `  - ${v.name} (${v.establishment_type || 'venue'}, ${v.neighbourhood || 'Vancouver'}, music: ${(v.music_types || []).join('/')||'varied'}) → ${v.url}`)
  .join('\n');

// Build tag options for GPT to choose from
const availableTags = [
  ...(ctx.existing_blog_tags || []),
  ...pick.focus.split(' ')
].filter((t, i, a) => a.indexOf(t) === i).join(', ');

return [{
  json: {
    topic: pick.topic,
    music_type: pick.music,
    site_url: ctx.site_url || 'https://yvradvisory.ca',
    key_pages: ctx.key_pages || {},
    venue_list: venueLines,
    available_tags: availableTags,
    all_music_types: (ctx.all_music_types || []).join(', '),
    all_vibe_tags: (ctx.all_vibe_tags || []).join(', '),
  }
}];

// Merge Reddit + Google results into a concise research brief for GPT.
// Reddit node result
const redditData = $('Reddit Search').item.json;
const googleData = $('Google Search (optional)').item.json;
const topicCtx = $('Pick Topic & Build Context').item.json;

let redditInsights = '';
try {
  const posts = (redditData?.data?.children || []).slice(0, 4);
  redditInsights = posts.map(p => {
    const d = p.data;
    return `• r/vancouver: "${d.title}" (${d.score} upvotes, ${d.num_comments} comments) — ${d.url}`;
  }).join('\n');
} catch(e) { redditInsights = 'No Reddit data available.'; }

let googleInsights = '';
try {
  const items = (googleData?.items || []).slice(0, 3);
  googleInsights = items.map(i => `• ${i.title} — ${i.link}`).join('\n');
} catch(e) { googleInsights = ''; }

return [{
  json: {
    ...topicCtx,
    reddit_insights: redditInsights,
    google_insights: googleInsights,
  }
}];

