// Parse GPT response and build the webhook payload.
const raw = $input.item.json.message.content;
let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  const cleaned = raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  parsed = JSON.parse(cleaned);
}

// Validate required fields
if (!parsed.title || !parsed.body) throw new Error('GPT response missing title or body');

// music_type: use GPT's answer if non-empty, else fall back to topic picker
const topicCtx = $('Pick Topic & Build Context').item.json;
const music = (parsed.music_type && parsed.music_type !== 'null' && parsed.music_type !== '')
  ? parsed.music_type
  : topicCtx.music_type || null;

// Tags: deduplicate, lowercase, max 8
const tags = [...new Set((parsed.tags || []).map(t => t.toLowerCase().trim()))].slice(0, 8);

// external_id: stable per-topic so re-runs in same week are idempotent updates
const week = Math.floor(Date.now() / (1000 * 60 * 60 * 24 * 7));
const topicSlug = topicCtx.topic.replace(/[^a-z0-9]+/gi, '-').toLowerCase().slice(0, 40);

return [{
  json: {
    title: parsed.title,
    summary: parsed.summary || null,
    body: parsed.body,
    author: parsed.author || 'YVR Advisory',
    tags,
    music_type: music,
    is_published: true,
    external_id: `n8n-blog-w${week}-${topicSlug}`,
    cover_image_url: null
  }
}];

const res = $input.item.json;
const statusCode = res.statusCode;
const body = res.body;

if (statusCode !== 200 && statusCode !== 201) {
  throw new Error(`YVR API error ${statusCode}: ${JSON.stringify(body)}`);
}

console.log(`Blog post ${body.action}: ID=${body.post_id} slug=${body.slug}`);

return [{ json: {
  success: true,
  action: body.action,
  post_id: body.post_id,
  slug: body.slug,
  url: 'https://yvradvisory.ca/blog/' + body.slug
}}];
